function NavBar({ page, setPage }) {
  const [open, setOpen] = useState(false);
  const go = (id) => {
    setPage(id);
    setOpen(false);
  };
  return (
    <header className="nav-shell">
      <nav className="nav-inner">
        <button className="brand" onClick={() => go("home")}>
          <span className="brand-mark">DM</span>
          <span className="brand-text">
            Daniel Manduku <em>MP Nyaribari Masaba</em>
          </span>
        </button>

        <div className="nav-links">
          {PAGES.map((p) => (
            <button
              key={p.id}
              className={"nav-link" + (page === p.id ? " active" : "")}
              onClick={() => go(p.id)}
            >
              {p.label}
            </button>
          ))}
          <button className="nav-cta" onClick={() => go("join")}>
            Join the Movement
          </button>
        </div>

        <button className="hamburger" aria-label="Menu" onClick={() => setOpen((o) => !o)}>
          {open ? <X size={22} /> : <Menu size={22} />}
        </button>
      </nav>

      <div className={"nav-mobile" + (open ? " open" : "")}>
        {PAGES.map((p) => (
          <button
            key={p.id}
            className={"nav-mobile-link" + (page === p.id ? " active" : "")}
            onClick={() => go(p.id)}
          >
            {p.label}
            <ChevronRight size={16} />
          </button>
        ))}
        <button className="nav-mobile-link nav-mobile-cta" onClick={() => go("join")}>
          Join the Movement
          <ArrowRight size={16} />
        </button>
      </div>
    </header>
  );
}

/* ============================================================
   MOTION HERO (Home page)
   ============================================================ */
function MotionHero({ setPage }) {
  const wrapRef = useRef(null);
  const [progress, setProgress] = useState(0);
  const reduced = useRef(prefersReducedMotion());
  const [slide, setSlide] = useState(0);

  // Auto-advancing background slideshow (stays still if the visitor prefers reduced motion)
  useEffect(() => {
    if (reduced.current) return undefined;
    const id = window.setInterval(() => {
      setSlide((s) => (s + 1) % HERO_SLIDES.length);
    }, 5500);
    return () => window.clearInterval(id);
  }, []);

  useEffect(() => {
    if (reduced.current) {
      setProgress(1);
      return undefined;
    }
    let raf = null;
    const onScroll = () => {
      if (raf) return;
      raf = requestAnimationFrame(() => {
        raf = null;
        const el = wrapRef.current;
        if (!el) return;
        const rect = el.getBoundingClientRect();
        const total = el.offsetHeight - window.innerHeight;
        setProgress(clamp(-rect.top / Math.max(total, 1), 0, 1));
      });
    };
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, []);

  const p1 = clamp(progress / 0.3, 0, 1);
  const p2 = clamp((progress - 0.3) / 0.3, 0, 1);
  const p3 = clamp((progress - 0.6) / 0.4, 0, 1);

  const imgScale = lerp(1.08, 0.88, p1) - lerp(0, 0.16, p3);
  const imgTranslateX = lerp(0, -16, p3);
  const imgTranslateY = lerp(30, 0, p1);
  const imgClip = lerp(16, 2, p1);
  const prevSlide = (slide - 1 + HERO_SLIDES.length) % HERO_SLIDES.length;

  return (
    <div ref={wrapRef} className="hero-wrap">
      <div className="hero-sticky">
        <div className="hero-slides" aria-hidden="true">
          {HERO_SLIDES.map((src, i) => (
            <img
              key={i}
              src={src}
              alt=""
              className={"hero-slide" + (i === slide ? " active" : i === prevSlide ? " leaving" : "")}
            />
          ))}
        </div>
        <div className="hero-bg" />
        <div className="hero-grid">
          <div
            className="hero-portrait"
            style={{
              transform: `translate(${imgTranslateX}%, ${imgTranslateY}px) scale(${imgScale})`,
              clipPath: `polygon(${imgClip}% 0%, 100% 0%, ${100 - imgClip * 0.4}% 100%, 0% 100%)`,
            }}
          >
            <img src={IMG.lawn} alt="Hon. Dr. Daniel Ogwoka Manduku, MP Nyaribari Masaba" />
            <div className="hero-portrait-frame" />
          </div>

          <div
            className="hero-copy"
            style={{ opacity: p2, transform: `translateY(${lerp(36, 0, p2)}px)` }}
          >
            <p className="hero-eyebrow">
              Hon. Dr. Daniel Ogwoka Manduku <span className="dot">·</span> MP Nyaribari Masaba
            </p>
            <h1>Tokore Egasi Amo n' Obwanchani.</h1>
            <p className="hero-sub">
              Let us work together with love. Visible. Measurable. People-focused. About KSh 800+ M
              in national government infrastructure and CDF delivery across Nyaribari Masaba, and
              a 2027 re-election bid focused on broad-based development.
            </p>

            <div
              className="hero-cta-row"
              style={{
                opacity: p3,
                transform: `translateY(${lerp(24, 0, p3)}px)`,
                pointerEvents: p3 > 0.5 ? "auto" : "none",
              }}
            >
              <button className="btn btn-accent" onClick={() => setPage("projects")}>
                See the Ward Record <ArrowRight size={16} />
              </button>
              <button className="btn btn-outline" onClick={() => setPage("agenda")}>
                2027–2032 Agenda
              </button>
            </div>
          </div>
        </div>
        <div className="hero-scroll-hint" style={{ opacity: 1 - p1 }}>
          <span>Scroll</span>
          <div className="hero-scroll-line" />
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   STATS COUNTER
   ============================================================ */
function StatCard({ stat }) {
  const [ref, inView] = useInView(0.4);
  const val = useCountUp(stat.value, inView);
  const text = val.toLocaleString("en-US", {
    minimumFractionDigits: stat.decimals,
    maximumFractionDigits: stat.decimals,
  });
  const Icon = stat.icon;
  return (
    <div className="bento-card" ref={ref}>
      <Icon size={22} className="stat-icon" />
      <div className="bento-number small">
        {stat.prefix}
        {text}
        {stat.suffix}
      </div>
      <p className="bento-label">{stat.label}</p>
    </div>
  );
}

function StatsSection() {
  return (
    <section className="section">
      <div className="section-head">
        <p className="kicker">The record in numbers</p>
        <h2>Visible. Measurable. People-focused.</h2>
      </div>
      <div className="bento-grid">
        {STATS.map((s, i) => (
          <StatCard stat={s} key={i} />
        ))}
      </div>
    </section>
  );
}

