/* ============================================================
   CONTACT PAGE
   ============================================================ */
function ContactForm() {
  const toast = useToast();
  const { values, set, errors, setErrors } = useFormState({ name: "", email: "", message: "" });
  const [loading, setLoading] = useState(false);

  const validate = () => {
    const e = {};
    if (!values.name.trim()) e.name = "Enter your full name.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) e.email = "Enter a valid email address.";
    if (!values.message.trim()) e.message = "Write a short message.";
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const submit = (ev) => {
    ev.preventDefault();
    if (!validate()) return;
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      toast("Message sent. Thank you for reaching out.");
      set("message", "");
    }, 1200);
  };

  return (
    <form className="pay-card" onSubmit={submit} noValidate>
      <div className="pay-card-head">
        <span className="pay-badge">Contact</span>
        <h3>Send a message</h3>
      </div>
      <label className="field">
        <span>Full name</span>
        <input value={values.name} onChange={(e) => set("name", e.target.value)} />
        {errors.name && <em className="error">{errors.name}</em>}
      </label>
      <label className="field">
        <span>Email</span>
        <input value={values.email} onChange={(e) => set("email", e.target.value)} placeholder="you@email.com" />
        {errors.email && <em className="error">{errors.email}</em>}
      </label>
      <label className="field">
        <span>Message</span>
        <textarea rows={4} value={values.message} onChange={(e) => set("message", e.target.value)} />
        {errors.message && <em className="error">{errors.message}</em>}
      </label>
      <button className="btn btn-accent full" disabled={loading} type="submit">
        {loading ? "Sending…" : "Send Message"} <Send size={16} />
      </button>
      <p className="fine-print">
        This form is a demonstration. Connect it to an email service or backend to receive
        messages live.
      </p>
    </form>
  );
}

