/* ============================================================
   JOIN THE CAMPAIGN TEAM
   ============================================================ */
function JoinForm() {
  const toast = useToast();
  const { values, set, errors, setErrors } = useFormState({
    name: "",
    phone: "",
    ward: "",
    email: "",
    message: "",
  });
  const [loading, setLoading] = useState(false);

  const validate = () => {
    const e = {};
    if (!values.name.trim()) e.name = "Enter your full name.";
    if (!/^\+?[0-9]{9,13}$/.test(values.phone.replace(/\s+/g, ""))) {
      e.phone = "Enter a valid phone number, e.g. 0712345678.";
    }
    if (!values.ward) e.ward = "Choose your ward.";
    if (values.email.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
      e.email = "Enter a valid email address.";
    }
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const submit = (ev) => {
    ev.preventDefault();
    if (!validate()) return;
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      toast("Welcome to the team! The campaign will be in touch soon.");
      ["name", "phone", "ward", "email", "message"].forEach((k) => set(k, ""));
    }, 1200);
  };

  return (
    <form className="pay-card" onSubmit={submit} noValidate>
      <div className="pay-card-head">
        <span className="pay-badge">Campaign team</span>
        <h3>Sign up to join</h3>
      </div>
      <label className="field">
        <span>Full name</span>
        <input value={values.name} onChange={(e) => set("name", e.target.value)} />
        {errors.name && <em className="error">{errors.name}</em>}
      </label>
      <label className="field">
        <span>Phone number</span>
        <input
          value={values.phone}
          onChange={(e) => set("phone", e.target.value)}
          placeholder="0712345678"
          inputMode="tel"
        />
        {errors.phone && <em className="error">{errors.phone}</em>}
      </label>
      <label className="field">
        <span>Ward</span>
        <select value={values.ward} onChange={(e) => set("ward", e.target.value)}>
          <option value="">Select your ward</option>
          {WARDS.map((w) => (
            <option key={w} value={w}>
              {w}
            </option>
          ))}
        </select>
        {errors.ward && <em className="error">{errors.ward}</em>}
      </label>
      <label className="field">
        <span>Email (optional)</span>
        <input value={values.email} onChange={(e) => set("email", e.target.value)} placeholder="you@email.com" />
        {errors.email && <em className="error">{errors.email}</em>}
      </label>
      <label className="field">
        <span>How would you like to help? (optional)</span>
        <textarea rows={3} value={values.message} onChange={(e) => set("message", e.target.value)} />
      </label>
      <button className="btn btn-accent full" disabled={loading} type="submit">
        {loading ? "Submitting…" : "Join the Campaign Team"} <Send size={16} />
      </button>
      <p className="fine-print">
        This form is a demonstration. Connect it to an email service or backend to receive
        sign-ups live.
      </p>
    </form>
  );
}

