/* ============================================================
   APP
   ============================================================ */
export default function App() {
  const [page, setPage] = useState("home");
  const [toast, setToast] = useState(null);

  // Every page change, from any button or link, starts at the top
  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }, [page]);

  const showToast = useCallback((msg) => {
    setToast(msg);
    window.clearTimeout(showToast._t);
    showToast._t = window.setTimeout(() => setToast(null), 3600);
  }, []);

  let PageComp;
  if (page === "home") PageComp = <HomePage setPage={setPage} />;
  else if (page === "about") PageComp = <AboutPage />;
  else if (page === "agenda") PageComp = <AgendaPage />;
  else if (page === "projects") PageComp = <ProjectsPage />;
  else if (page === "gallery") PageComp = <GalleryPage />;
  else if (page === "news") PageComp = <NewsPage />;
  else if (page === "contact") PageComp = <ContactPage />;
  else if (page === "join") PageComp = <JoinPage />;

  return (
    <ToastCtx.Provider value={showToast}>
      <div className="app-root">
        <style>{CSS}</style>
        <NavBar page={page} setPage={setPage} />
        <main>{PageComp}</main>
        <Footer setPage={setPage} />
        <ToastHost toast={toast} />
      </div>
    </ToastCtx.Provider>
  );
}

/* ============================================================
   STYLES
   ============================================================ */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Work+Sans:wght@400;500;600;700&display=swap');

:root{
  --navy-950:#0A1B33;
  --navy-900:#10294A;
  --navy-800:#17386A;
  --orange-400:#F59A57;
  --orange-500:#F2802F;
  --orange-600:#E06A18;
  --orange-700:#C2540E;
  --paper:#FAF8F5;
  --paper-dim:#EFECE6;
  --charcoal:#14202F;
  --charcoal-60:rgba(20,32,47,.66);
  --line:rgba(16,41,74,.14);
  --radius-s:6px;
  --radius-m:14px;
}

*{box-sizing:border-box;}
.app-root{font-family:'Work Sans',sans-serif;color:var(--charcoal);background:var(--paper);}
.app-root h1,.app-root h2,.app-root h3,.app-root h4{font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;color:var(--navy-900);line-height:1.14;margin:0;}
.app-root p{margin:0;line-height:1.6;color:var(--charcoal-60);}
button{font-family:inherit;cursor:pointer;}
input,select,textarea{font-family:inherit;}
@media (prefers-reduced-motion: reduce){ *{scroll-behavior:auto!important;} }

.kicker{font-family:'Work Sans',sans-serif;font-size:.85rem;letter-spacing:.02em;color:var(--orange-700);font-weight:700;margin:0 0 .6rem;}
.kicker-icon{display:flex;align-items:center;gap:.4rem;}
.section-sub{margin-top:.6rem;font-size:.98rem;}

/* NAV */
.nav-shell{position:sticky;top:0;z-index:50;backdrop-filter:blur(14px);background:rgba(250,248,245,.86);border-bottom:1px solid var(--line);}
.nav-inner{max-width:1240px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:.85rem 1.5rem;gap:1rem;}
.brand{display:flex;align-items:center;gap:.6rem;background:none;border:none;padding:0;}
.brand-mark{width:38px;height:38px;border-radius:50%;background:var(--navy-900);color:var(--orange-400);display:flex;align-items:center;justify-content:center;font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:.9rem;flex-shrink:0;}
.brand-mark.small{margin-bottom:.9rem;}
.brand-text{font-family:'Plus Jakarta Sans',sans-serif;font-size:1.02rem;color:var(--navy-900);text-align:left;font-weight:700;line-height:1.1;}
.brand-text em{font-family:'Work Sans',sans-serif;font-style:normal;color:var(--orange-700);display:block;font-size:.72rem;letter-spacing:.03em;margin-top:2px;font-weight:600;}
.nav-links{display:none;align-items:center;gap:1.3rem;}
.nav-link{background:none;border:none;font-size:.9rem;color:var(--charcoal-60);padding:.3rem 0;border-bottom:2px solid transparent;}
.nav-link.active{color:var(--navy-900);border-color:var(--orange-500);}
.broad-based-badge{background:var(--navy-900);color:#fff;font-size:.7rem;font-weight:700;letter-spacing:.04em;padding:.35rem .7rem;border-radius:999px;border:1px solid var(--orange-500);}
.broad-based-badge.light{background:var(--orange-500);color:var(--navy-950);border:none;display:inline-block;}
.hamburger{background:none;border:none;color:var(--navy-900);}
.nav-mobile{max-height:0;overflow:hidden;transition:max-height .35s ease;background:var(--paper);border-bottom:1px solid var(--line);}
.nav-mobile.open{max-height:460px;}
.nav-mobile-link{display:flex;width:100%;justify-content:space-between;align-items:center;background:none;border:none;border-top:1px solid var(--line);padding:.9rem 1.5rem;font-size:.95rem;color:var(--charcoal);text-align:left;}
.nav-mobile-link.active{color:var(--orange-700);font-weight:600;}
@media(min-width:980px){ .nav-links{display:flex;} .hamburger{display:none;} .nav-mobile{display:none;} }

/* HERO */
.hero-wrap{height:300vh;position:relative;}
.hero-sticky{position:sticky;top:0;height:100vh;overflow:hidden;background:linear-gradient(180deg,var(--navy-950),var(--navy-900));}
.hero-slides{position:absolute;inset:0;z-index:0;overflow:hidden;}
.hero-slide{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 28%;opacity:0;transform:translateX(7%) scale(1.06);transition:opacity 1.4s ease, transform 6.5s ease-out;will-change:opacity,transform;}
.hero-slide.active{opacity:1;transform:translateX(0) scale(1);}
.hero-slide.leaving{opacity:0;transform:translateX(-7%) scale(1.02);}
.hero-bg{position:absolute;inset:0;z-index:1;background:radial-gradient(circle at 75% 20%, rgba(242,128,47,.16), transparent 55%), linear-gradient(180deg, rgba(10,27,51,.6), rgba(16,41,74,.74));}
.hero-grid{position:relative;z-index:2;max-width:1240px;margin:0 auto;height:100%;display:grid;grid-template-columns:1fr;align-items:center;gap:1rem;padding:3.5rem 1.5rem;}
.hero-portrait{width:min(78vw,320px);aspect-ratio:3/4;margin:0 auto;position:relative;overflow:hidden;justify-self:center;}
.hero-portrait img{width:100%;height:100%;object-fit:cover;display:block;object-position:50% 12%;}
.hero-portrait-frame{position:absolute;inset:0;border:1.5px solid rgba(242,128,47,.6);pointer-events:none;}
.hero-copy{color:#FAF8F5;text-align:center;max-width:640px;margin:1.5rem auto 0;text-shadow:0 2px 18px rgba(0,0,0,.55);}
.hero-copy h1{color:var(--orange-500);font-size:clamp(1.9rem,5vw,3rem);margin:.5rem 0 1rem;}
.hero-copy .hero-eyebrow{color:#FFFFFF;font-size:.85rem;letter-spacing:.03em;font-weight:600;}
.hero-copy .hero-eyebrow .dot{color:var(--orange-500);}
.hero-copy .hero-sub{color:#FFFFFF;font-size:1.02rem;max-width:540px;margin:0 auto;}
.hero-cta-row{display:flex;gap:.9rem;justify-content:center;flex-wrap:wrap;margin-top:2.4rem;padding-bottom:1.2rem;}
.hero-scroll-hint{position:absolute;z-index:2;bottom:28px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:.4rem;color:rgba(250,248,245,.6);font-size:.72rem;letter-spacing:.08em;}
.hero-scroll-line{width:1px;height:30px;background:linear-gradient(180deg,rgba(250,248,245,.7),transparent);}
@media(max-width:899px){
  .hero-grid{padding:4.75rem 1.25rem 1.5rem;gap:0;}
  .hero-portrait{width:min(56vw,280px,28vh);}
  .hero-copy{margin-top:2.5rem;}
  .hero-copy h1{font-size:clamp(1.55rem,7.2vw,2.1rem);}
  .hero-copy .hero-sub{font-size:.95rem;}
  .hero-cta-row{margin-top:1.4rem;padding-bottom:0;}
}
@media(max-width:899px) and (max-height:700px){
  .hero-portrait{width:min(48vw,22vh);}
  .hero-copy{margin-top:2.25rem;}
  .hero-copy .hero-sub{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;}
}
@media(min-width:900px){
  .hero-grid{grid-template-columns:.9fr 1.1fr;text-align:left;}
  .hero-portrait{justify-self:start;width:340px;}
  .hero-copy{text-align:left;margin:0;}
  .hero-cta-row{justify-content:flex-start;}
  .hero-sub{margin:0;}
}

/* BUTTONS */
.btn{display:inline-flex;align-items:center;gap:.5rem;border-radius:999px;padding:.85rem 1.6rem;font-size:.92rem;font-weight:600;border:1.5px solid transparent;transition:transform .18s ease, background .18s ease;}
.btn:hover{transform:translateY(-1px);}
.btn.full{width:100%;justify-content:center;}
.btn-accent{background:var(--orange-500);color:var(--navy-950);}
.btn-accent:hover{background:var(--orange-400);}
.btn-outline{border-color:rgba(250,248,245,.6);color:#FAF8F5;background:transparent;}
.btn:disabled{opacity:.7;cursor:default;}

/* SECTIONS */
.section{max-width:1180px;margin:0 auto;padding:5rem 1.5rem;}
.section-head{max-width:640px;margin-bottom:2.4rem;}
.section-head h2{font-size:clamp(1.5rem,3vw,2.1rem);}
.page-pad{padding-top:1rem;}

/* BENTO / STATS */
.bento-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1.1rem;}
@media(min-width:800px){.bento-grid{grid-template-columns:repeat(4,1fr);}}
.bento-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius-m);padding:1.5rem;transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.stat-icon{color:var(--orange-700);margin-bottom:.7rem;}
.bento-number{font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:1.7rem;color:var(--orange-700);}
.bento-number.small{font-size:1.45rem;}
.bento-label{font-size:.88rem;margin-top:.5rem;}
.record-grid{display:grid;grid-template-columns:1fr;gap:1.1rem;}
@media(min-width:860px){.record-grid{grid-template-columns:repeat(3,1fr);}}
.record-icon{color:var(--orange-700);margin-bottom:.8rem;}
.record-title{font-size:1.1rem;}

/* SPLIT */
.split-section{display:grid;grid-template-columns:1fr;gap:2.4rem;align-items:center;}
.split-image img{width:100%;border-radius:var(--radius-m);display:block;object-fit:cover;aspect-ratio:4/5;object-position:50% 20%;}
.split-copy h2{font-size:clamp(1.5rem,3vw,2.1rem);margin-bottom:1rem;}
.split-copy p{margin-bottom:1rem;}
.link-cta{display:inline-flex;align-items:center;gap:.4rem;background:none;border:none;color:var(--orange-700);font-weight:600;padding:0;margin-top:.4rem;}
.link-cta.light{color:var(--orange-400);}
@media(min-width:860px){ .split-section{grid-template-columns:.85fr 1.15fr;} }
.cred-row{display:flex;flex-wrap:wrap;gap:.5rem;margin:.4rem 0 .8rem;}
.cred-chip{background:var(--navy-900);color:#fff;font-size:.78rem;font-weight:600;padding:.35rem .8rem;border-radius:999px;}
.fine-print.left{margin-top:0;}

/* WARDS STRIP */
.ward-chips{display:flex;flex-wrap:wrap;gap:.7rem;margin-bottom:1.4rem;}
.ward-chip-lg{display:inline-flex;align-items:center;gap:.4rem;background:#fff;border:1px solid var(--line);color:var(--navy-900);font-weight:600;font-size:.95rem;padding:.65rem 1.2rem;border-radius:999px;}

/* SLOGAN BANNER */
.slogan-banner{background:var(--navy-950);border-radius:var(--radius-m);overflow:hidden;display:grid;grid-template-columns:1fr;}
.slogan-banner-copy{padding:2.4rem;}
.slogan-banner-copy h2{color:#fff;margin:1rem 0;}
.slogan-banner-copy p{color:rgba(250,248,245,.78);}
.slogan-banner-image img{width:100%;height:100%;object-fit:cover;display:block;min-height:240px;object-position:50% 25%;}
@media(min-width:860px){.slogan-banner{grid-template-columns:1.1fr .9fr;}}

/* TIMELINE / TWO COL */
.two-col{display:grid;grid-template-columns:1fr;gap:3rem;}
@media(min-width:900px){.two-col{grid-template-columns:1fr 1fr;gap:3.5rem;}}
.timeline{display:flex;flex-direction:column;gap:1.4rem;}
.timeline-item{display:flex;gap:1rem;align-items:flex-start;}
.timeline-dot{width:10px;height:10px;border-radius:50%;background:var(--orange-500);margin-top:.4rem;flex-shrink:0;}
.timeline-year{color:var(--orange-700);font-size:.78rem;font-weight:700;}
.timeline-body h4{font-size:1.02rem;font-family:'Plus Jakarta Sans',sans-serif;margin:.2rem 0 .3rem;}
.timeline-body p{font-size:.88rem;}

/* AGENDA (dark) */
.agenda-page{background:var(--navy-900);}
.agenda-page .section-head h2,.agenda-page .section-head .section-sub{color:#fff;}
.agenda-page .kicker{color:var(--orange-400);}
.manifesto-grid{display:grid;grid-template-columns:1fr;gap:1.2rem;}
@media(min-width:760px){.manifesto-grid{grid-template-columns:repeat(2,1fr);}}
.manifesto-card{background:rgba(250,248,245,.06);border:1px solid rgba(250,248,245,.16);border-radius:var(--radius-m);padding:1.8rem;color:rgba(250,248,245,.8);transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.manifesto-card svg{color:var(--orange-400);margin-bottom:.9rem;}
.manifesto-card h3{color:#fff;font-size:1.12rem;margin-bottom:.6rem;}
.manifesto-card p{font-size:.92rem;color:rgba(250,248,245,.78);}

/* PROJECTS / NEWS */
.filter-row{display:flex;gap:.6rem;flex-wrap:wrap;margin-bottom:2rem;}
.filter-chip{border:1px solid var(--line);background:#fff;border-radius:999px;padding:.5rem 1.1rem;font-size:.86rem;color:var(--charcoal-60);display:inline-flex;align-items:center;gap:.45rem;}
.filter-chip.active{background:var(--navy-900);border-color:var(--navy-900);color:#fff;}
.filter-count{background:rgba(16,41,74,.1);border-radius:999px;font-size:.72rem;font-weight:700;padding:.1rem .5rem;}
.filter-chip.active .filter-count{background:var(--orange-500);color:var(--navy-950);}
.project-grid,.news-grid{display:grid;grid-template-columns:1fr;gap:1.4rem;}
@media(min-width:760px){.project-grid,.news-grid{grid-template-columns:repeat(2,1fr);}}
@media(min-width:1040px){.project-grid,.news-grid{grid-template-columns:repeat(3,1fr);}}
.project-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius-m);overflow:hidden;transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.ward-card-top{background:linear-gradient(135deg,var(--navy-900),var(--navy-800));padding:1.1rem 1.3rem;display:flex;align-items:center;justify-content:space-between;}
.ward-chip{background:rgba(242,128,47,.18);color:var(--orange-400);font-size:.74rem;font-weight:700;padding:.3rem .75rem;border-radius:999px;}
.ward-icon{color:var(--orange-400);}
.project-image{position:relative;aspect-ratio:4/3;}
.project-image img{width:100%;height:100%;object-fit:cover;display:block;}
.project-image.contain{background:var(--navy-950);}
.project-image.contain img{object-fit:contain;}
a.project-image{display:block;}
.project-tag{position:absolute;top:.8rem;left:.8rem;background:rgba(10,27,51,.88);color:#fff;font-size:.72rem;padding:.3rem .7rem;border-radius:999px;display:flex;align-items:center;gap:.3rem;}
.project-body{padding:1.3rem;}
.project-body h3{font-size:1.05rem;margin-bottom:.5rem;}
.project-body p{font-size:.88rem;}
.news-date{font-size:.76rem;color:var(--orange-700);font-weight:700;display:flex;align-items:center;gap:.35rem;margin-bottom:.35rem;}
.news-play{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#fff;background:rgba(10,27,51,.28);transition:background .2s ease;}
a.project-image:hover .news-play{background:rgba(242,128,47,.35);}
.news-watch{display:inline-flex;align-items:center;gap:.35rem;margin-top:.8rem;font-size:.84rem;font-weight:600;color:var(--orange-700);text-decoration:none;}

/* GALLERY */
.gallery-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.9rem;}
@media(min-width:700px){.gallery-grid{grid-template-columns:repeat(4,1fr);}}
.gallery-item{position:relative;border-radius:var(--radius-m);overflow:hidden;aspect-ratio:1/1;border:1px solid var(--line);transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;padding:0;background:none;display:block;text-align:left;}
.gallery-item img{width:100%;height:100%;object-fit:cover;display:block;}
.gallery-item.contain{background:var(--navy-950);}
.gallery-item.contain img{object-fit:contain;}
.gallery-caption{position:absolute;left:0;right:0;bottom:0;padding:1.6rem .8rem .7rem;background:linear-gradient(0deg,rgba(10,27,51,.94),rgba(10,27,51,.55) 60%,transparent);color:#fff;font-size:.78rem;line-height:1.35;opacity:0;transform:translateY(8px);transition:opacity .2s ease, transform .2s ease;}
.gallery-item:hover .gallery-caption,.gallery-item.show-caption .gallery-caption{opacity:1;transform:translateY(0);}
.video-grid{display:grid;grid-template-columns:1fr;gap:1.2rem;}
@media(min-width:700px){.video-grid{grid-template-columns:repeat(2,1fr);}}
@media(min-width:1040px){.video-grid{grid-template-columns:repeat(3,1fr);}}
.video-item{position:relative;display:block;border-radius:var(--radius-m);overflow:hidden;aspect-ratio:16/10;border:1px solid var(--line);transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.video-item img{width:100%;height:100%;object-fit:cover;display:block;}
.video-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#fff;background:rgba(10,27,51,.28);}
.video-caption{position:absolute;left:0;right:0;bottom:0;padding:.7rem .9rem;background:linear-gradient(0deg,rgba(10,27,51,.88),transparent);color:#fff;font-size:.82rem;display:flex;align-items:center;gap:.4rem;}

/* FORMS / CONTACT */
.contact-grid{display:grid;grid-template-columns:1fr;gap:1.6rem;}
@media(min-width:860px){.contact-grid{grid-template-columns:1.1fr .9fr;}}
.pay-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius-m);padding:1.8rem;}
.pay-card-head{display:flex;align-items:center;gap:.7rem;margin-bottom:1.4rem;}
.pay-card-head h3{font-size:1.15rem;}
.pay-badge{background:var(--navy-900);color:#fff;font-size:.72rem;padding:.3rem .7rem;border-radius:999px;font-family:'Work Sans',sans-serif;font-weight:600;}
.field{display:flex;flex-direction:column;gap:.35rem;margin-bottom:1.1rem;font-size:.85rem;color:var(--charcoal-60);}
.field input,.field select,.field textarea{border:1px solid var(--line);border-radius:var(--radius-s);padding:.7rem .85rem;font-size:.94rem;color:var(--charcoal);background:var(--paper);}
.field input:focus,.field select:focus,.field textarea:focus{outline:2px solid var(--orange-600);outline-offset:1px;}
.error{color:#B3401E;font-size:.78rem;font-style:normal;}
.fine-print{font-size:.76rem;margin-top:.9rem;color:var(--charcoal-60);}
.contact-info{background:var(--navy-900);border-radius:var(--radius-m);padding:1.8rem;color:rgba(250,248,245,.85);}
.contact-info-row{display:flex;gap:.8rem;align-items:flex-start;margin-bottom:1.3rem;color:var(--orange-400);}
.contact-info-row h4{color:#fff;font-size:.9rem;font-family:'Work Sans',sans-serif;margin-bottom:.2rem;}
.contact-info-row a{color:rgba(250,248,245,.88);font-size:.9rem;}
.contact-info-row p{color:rgba(250,248,245,.78);font-size:.9rem;}
.social-heading{color:#fff;font-size:.85rem;margin:1.2rem 0 .8rem;font-family:'Work Sans',sans-serif;}
.contact-socials{display:flex;flex-direction:column;gap:.8rem;}
.contact-socials a{display:flex;align-items:center;gap:.7rem;color:rgba(250,248,245,.88);font-size:.88rem;}
.contact-socials a:hover{color:var(--orange-400);}

/* CARD HOVER */
.bento-card:hover,.project-card:hover,.manifesto-card:hover,.gallery-item:hover,.video-item:hover{
  border-color:var(--orange-500);
  box-shadow:0 0 0 1px rgba(242,128,47,.4), 0 22px 44px -12px rgba(242,128,47,.32);
  transform:translateY(-3px);
}

/* FOOTER */
.site-footer{background:var(--navy-950);color:rgba(250,248,245,.8);margin-top:2rem;}
.footer-grid{max-width:1180px;margin:0 auto;padding:3.5rem 1.5rem 2rem;display:grid;grid-template-columns:1fr;gap:2.2rem;}
@media(min-width:800px){.footer-grid{grid-template-columns:1.3fr 1fr 1fr;}}
.footer-col p{font-size:.86rem;color:rgba(250,248,245,.68);margin-bottom:.6rem;display:flex;align-items:center;gap:.5rem;}
.footer-col h5{color:#fff;font-family:'Work Sans',sans-serif;font-size:.85rem;letter-spacing:.02em;margin-bottom:1rem;}
.footer-col button{display:block;background:none;border:none;color:rgba(250,248,245,.72);font-size:.86rem;padding:.35rem 0;text-align:left;}
.footer-col button:hover{color:var(--orange-400);}
.social-row{display:flex;gap:.7rem;margin-top:.8rem;}
.social-row a{width:36px;height:36px;border-radius:50%;background:var(--orange-500);color:var(--navy-950);display:flex;align-items:center;justify-content:center;transition:background .2s ease, transform .2s ease;}
.social-row a:hover{background:var(--orange-400);transform:translateY(-2px);}
.footer-bottom{border-top:1px solid rgba(250,248,245,.15);text-align:center;font-size:.72rem;color:rgba(250,248,245,.55);padding:1.2rem 1.5rem;}

/* HEADER CTA + JOIN PAGE */
.nav-cta{background:var(--orange-500);color:var(--navy-950);border:none;border-radius:999px;padding:.55rem 1.15rem;font-size:.82rem;font-weight:700;white-space:nowrap;transition:background .2s ease, transform .2s ease;}
.nav-cta:hover{background:var(--orange-400);transform:translateY(-1px);}
.nav-mobile-link.nav-mobile-cta{background:var(--orange-500);color:var(--navy-950);font-weight:700;border-top:none;}
.join-grid{display:grid;grid-template-columns:1fr;gap:1.6rem;}
@media(min-width:860px){.join-grid{grid-template-columns:1.1fr .9fr;}}
.join-aside{position:relative;border-radius:var(--radius-m);overflow:hidden;min-height:320px;}
.join-aside img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 25%;}
.join-aside-copy{position:absolute;left:0;right:0;bottom:0;padding:2.6rem 1.6rem 1.6rem;background:linear-gradient(0deg,rgba(10,27,51,.94),rgba(10,27,51,.6) 60%,transparent);}
.join-aside-copy h3{color:#fff;font-size:1.25rem;margin-bottom:.4rem;}
.join-aside-copy p{color:rgba(250,248,245,.88);}

/* TOAST */
.toast-host{position:fixed;bottom:1.6rem;left:50%;transform:translateX(-50%);background:var(--navy-950);color:#fff;padding:.85rem 1.3rem;border-radius:999px;display:flex;align-items:center;gap:.6rem;font-size:.86rem;box-shadow:0 12px 30px rgba(0,0,0,.35);z-index:100;max-width:90vw;}
.toast-host svg{color:var(--orange-400);flex-shrink:0;}
`;
